            str(route), is_endpoint
        )
        self._regex_dict = {}
        self._match_regex_dict = {}
        self._is_endpoint = is_endpoint
        self.name = name

    def match(self, path):
        # Only use regex overhead if there are converters.
        if self.converters:
            if match := self.match_regex.search(path):
