# A well-formed percent-encoded octet, e.g. "%2F" or "%c3".
_PERCENT_ENCODED_RE = r"%[0-9A-Fa-f]{2}"

# The raw-path counterpart of a converter's capture regex. Matching is done
# against the still-encoded path so that an encoded slash ("%2F") cannot
# introduce a new path level; in addition to the converter's own characters,
# the capture therefore accepts (interleaved) well-formed percent escapes.
# Each capture is percent-decoded exactly once before the converter validates
# it, so loosening the regex here cannot let an invalid decoded value
# through.
def _match_capture(parameter, converter_regex):
    return (
        f"(?P<{parameter}>"
        f"(?:{_PERCENT_ENCODED_RE}|{converter_regex})+)"
    )

