_HEX_DIGITS = frozenset("0123456789abcdefABCDEF")


def _decode_route_capture(value):
    """
    Percent-decode a captured route component exactly once.

    The resolver matches the raw, still-encoded path, so every captured
    component is decoded here before being handed to its converter. Every
    '%' must introduce a well-formed percent-encoded octet and the decoded
    bytes must be valid UTF-8; otherwise ValueError is raised so the caller
    can treat the route as non-matching rather than treating a malformed
    escape as trailing literal characters.
    """
    if "%" not in value:
        return value
    for fragment in value.split("%")[1:]:
        if (
            len(fragment) < 2
            or fragment[0] not in _HEX_DIGITS
            or fragment[1] not in _HEX_DIGITS
        ):
            raise ValueError("Malformed percent-encoding in route component")
    try:
        return unquote(value, errors="strict")
    except UnicodeDecodeError as e:
        raise ValueError("Route component is not valid UTF-8") from e

